Here’s a complex smart contract example in Solidity, featuring multi-signature governance, token staking, and automated reward distribution. This contract uses OpenZeppelin libraries for security and modularity:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract AdvancedGovernanceStaking is Ownable, ReentrancyGuard {
    // Structs
    struct Proposal {
        uint256 id;
        address proposer;
        string description;
        uint256 votesFor;
        uint256 votesAgainst;
        bool executed;
        uint256 deadline;
    }

    struct Staker {
        uint256 stakeAmount;
        uint256 rewardDebt;
        uint256 lastStakeTime;
    }

    // State variables
    IERC20 public rewardToken;
    IERC20 public governanceToken;
    uint256 public constant VOTING_PERIOD = 7 days;
    uint256 public constant STAKING_REWARD_RATE = 0.05e18; // 5% annual
    uint256 public totalStaked;
    uint256 public proposalCounter;

    // Mappings
    mapping(address => Staker) public stakers;
    mapping(uint256 => Proposal) public proposals;
    mapping(address => mapping(uint256 => bool)) public votes;

    // Events
    event Staked(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 amount);
    event ProposalCreated(uint256 indexed id, address proposer);
    event Voted(uint256 indexed proposalId, address indexed voter, bool support);

    // Modifiers
    modifier onlyStaker() {
        require(stakers[msg.sender].stakeAmount > 0, "Not a staker");
        _;
    }

    modifier proposalExists(uint256 _id) {
        require(_id < proposalCounter, "Proposal DNE");
        _;
    }

    // Constructor
    constructor(address _rewardToken, address _governanceToken) {
        rewardToken = IERC20(_rewardToken);
        governanceToken = IERC20(_governanceToken);
    }

    // Staking functions
    function stake(uint256 _amount) external nonReentrant {
        require(_amount > 0, "Zero amount");
        governanceToken.transferFrom(msg.sender, address(this), _amount);
        uint256 pending = calculatePendingRewards(msg.sender);
        if (pending > 0) rewardToken.transfer(msg.sender, pending);

        Staker storage user = stakers[msg.sender];
        user.stakeAmount += _amount;
        user.rewardDebt = (user.stakeAmount * getAccumulatedRewardsPerShare()) / 1e18;
        user.lastStakeTime = block.timestamp;
        totalStaked += _amount;

        emit Staked(msg.sender, _amount);
    }

    // Governance functions
    function createProposal(string memory _description) external onlyStaker {
        require(bytes(_description).length > 0, "Empty proposal");
        uint256 _id = proposalCounter++;
        proposals[_id] = Proposal({
            id: _id,
            proposer: msg.sender,
            description: _description,
            votesFor: 0,
            votesAgainst: 0,
            executed: false,
            deadline: block.timestamp + VOTING_PERIOD
        });
        emit ProposalCreated(_id, msg.sender);
    }

    function vote(uint256 _id, bool _support) external onlyStaker proposalExists(_id) {
        Proposal storage p = proposals[_id];
        require(block.timestamp < p.deadline, "Voting closed");
        require(!votes[msg.sender][_id], "Already voted");

        uint256 votingPower = stakers[msg.sender].stakeAmount;
        if (_support) p.votesFor += votingPower;
        else p.votesAgainst += votingPower;
        votes[msg.sender][_id] = true;

        emit Voted(_id, msg.sender, _support);
    }

    // Reward calculations
    function calculatePendingRewards(address _user) public view returns (uint256) {
        Staker storage user = stakers[_user];
        uint256 accRewards = getAccumulatedRewardsPerShare();
        return (user.stakeAmount * accRewards) / 1e18 - user.rewardDebt;
    }

    function getAccumulatedRewardsPerShare() public view returns (uint256) {
        if (totalStaked == 0) return 0;
        uint256 timeElapsed = block.timestamp - lastRewardTime;
        uint256 rewardsToAdd = (totalStaked * STAKING_REWARD_RATE * timeElapsed) / 365 days;
        return accRewardsPerShare + rewardsToAdd;
    }

    // Admin functions
    function emergencyWithdrawTokens(address _token, uint256 _amount) external onlyOwner {
        IERC20(_token).transfer(owner(), _amount);
    }
}
```

**Key Features:**
1. **Multi-Token System**: Uses separate governance and reward tokens
2. **Governance Mechanism**: Stakers can create proposals and vote with their stake as voting power
